/*
 * A191135  Increasing sequence generated by these rules: a(1)=1, and if x is
 *          in a then 3x+1 and 4x are in a.
 * https://oeis.org/A191135
 *
 * Offset:    1    (a(1) is the first term)
 * Keywords:  nonn
 * Formula:   not stated
 * Range:     u8 n <= 8, u16 n <= 187, u32 n <= 10000, u64 n <= 10000,
 *            u128 n <= 10000, big any n
 * Helpers:   heap_swap
 *
 * Sequence data from the OEIS (https://oeis.org), licensed CC BY-SA 4.0.
 */

/* 
 * Formula: a(1)=1, and if x∈a then 3x+1 and 4x are in a.
 * The following implementation expands the set in ascending order
 * using a min‑heap.  It stores each unique value once, so the array
 * `seq_arr` always contains the sequence in order.  The routine
 * works for any idx_t (uint64_t) and seq_t, including an arbitrary‑precision
 * integer class; it relies only on the arithmetic operators that seq_t
 * supports.
 */

#include <stdlib.h>
#include <stdbool.h>
#include "../utils/heap_swap.h"

/* --- dynamic array helper ------------------------------------------------ */
static void *grow_array(void **p, size_t *cap, size_t need, size_t elem_size) {
    if (*cap < need) {
        size_t new_cap = (*cap == 0) ? 64 : (*cap * 3) / 2;
        if (new_cap < need) new_cap = need;
        *p = realloc(*p, new_cap * elem_size);
        *cap = new_cap;
    }
    return *p;
}

/* --- min‑heap ---------------------------------------------------------------- */
static seq_t *heap_arr = NULL;      /* min‑heap array */
static size_t heap_cap = 0, heap_len = 0;

static void heap_push(seq_t val) {
    heap_arr = (seq_t *)grow_array((void**)&heap_arr, &heap_cap,
                                   heap_len + 1, sizeof(seq_t));
    size_t i = heap_len++;
    heap_arr[i] = val;
    while (i > 0) {
        size_t p = (i - 1) >> 1;
        if (heap_arr[p] <= heap_arr[i]) break;
        heap_swap(&heap_arr[p], &heap_arr[i]);
        i = p;
    }
}

static seq_t heap_pop(void) {
    seq_t root = heap_arr[0];
    heap_arr[0] = heap_arr[--heap_len];
    size_t i = 0;
    while (1) {
        size_t l = (i << 1) + 1;
        size_t r = l + 1;
        size_t m = i;
        if (l < heap_len && heap_arr[l] < heap_arr[m]) m = l;
        if (r < heap_len && heap_arr[r] < heap_arr[m]) m = r;
        if (m == i) break;
        heap_swap(&heap_arr[i], &heap_arr[m]);
        i = m;
    }
    return root;
}

/* --- unique value check ----------------------------------------------------- */
static seq_t *seen_arr = NULL;
static size_t seen_cap = 0, seen_len = 0;

static bool seen_contains(seq_t val) {
    for (size_t i = 0; i < seen_len; ++i)
        if (seen_arr[i] == val) return true;
    return false;
}

static void seen_append(seq_t val) {
    seen_arr = (seq_t *)grow_array((void**)&seen_arr, &seen_cap,
                                   seen_len + 1, sizeof(seq_t));
    seen_arr[seen_len++] = val;
}

/* --- sequence storage ------------------------------------------------------- */
static seq_t *seq_arr = NULL;
static size_t seq_cap = 0, seq_len = 0;
static bool initialized = false;

/* --- public function -------------------------------------------------------- */
seq_t a(idx_t n) {
    if (n <= 0) return (seq_t)0;      /* undefined for n<1 */

    if (!initialized) {
        /* initialise data structures */
        seq_arr = NULL;  seq_cap = 0;  seq_len = 0;
        heap_arr = NULL; heap_cap = 0; heap_len = 0;
        seen_arr = NULL; seen_cap = 0; seen_len = 0;

        heap_push((seq_t)1);
        seen_append((seq_t)1);
        initialized = true;
    }

    while (seq_len < (size_t)n) {
        seq_t x = heap_pop();
        seq_arr = (seq_t *)grow_array((void**)&seq_arr, &seq_cap,
                                      seq_len + 1, sizeof(seq_t));
        seq_arr[seq_len++] = x;

        /* generate successors */
        seq_t y1 = x * (seq_t)4;
        if (!seen_contains(y1)) {
            heap_push(y1);
            seen_append(y1);
        }
        seq_t y2 = x * (seq_t)3 + (seq_t)1;
        if (!seen_contains(y2)) {
            heap_push(y2);
            seen_append(y2);
        }
    }

    return seq_arr[n - 1];
}
